import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color, DoubleSide } from 'three/webgpu';
import { vec3, mix, uv, texture, screenUV } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;
  const group = new ThreeGroup();

  // 1. STAGE & PALETTE
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);
  const surfaceColor = new Color(colors.surface);

  // 2. BACKDROP / CARD BASE (Engineered Gradient Surface)
  // Dimensions fitting the hub frame comfortably for a feature card label
  const width = 3.6;
  const height = 1.8;
  const geometry = new ThreePlaneGeometry(width, height);

  // Create Node Material with Custom TSL Shading
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true
  });

  // TSL: Subtle grain + engineered vertical gradient (surface to ink)
  const vUv = uv();
  const gradNode = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), vUv.y);

  // Subtle procedural grain
  const grainSeed = screenUV().mul(200.0);
  const grain = grainSeed.x.sin().mul(grainSeed.y.cos()).fract().mul(0.04);
  const finalColorNode = gradNode.add(grain);

  material.colorNode = finalColorNode;

  const cardMesh = new ThreeMesh(geometry, material);
  group.add(cardMesh);

  // 3. TEXT LAYER (From Spec Verbatim: "Features 2")
  // Extract typography spec
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineCopy = textItems.find(item => item.role === 'headline' || item.text.includes('Features'))?.text ?? "Features 2";

  // Display sizes for display/headline as per instructions.
  // 39px translates to roughly ~0.18-0.22 scene units depending on layout block.
  const titleText = ctx.fontAtlas.createText(headlineCopy, {
    fontSize: 0.20,
    color: colors.paper,
    align: 'center'
  });

  // Offset slightly forward on Z to prevent z-fighting
  titleText.position.set(0, 0.15, 0.02);
  group.add(titleText);

  // Decorative Sub-label in JetBrains Mono ("ATELIER DEPARTEMENT")
  const subText = ctx.fontAtlas.createText("NOVA SYSTEM LABS", {
    fontSize: 0.07,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  subText.position.set(0, -0.22, 0.02);
  group.add(subText);

  // Geometric accent line (Signal Red)
  const lineGeom = new ThreePlaneGeometry(0.8, 0.02);
  const lineMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const lineMesh = new ThreeMesh(lineGeom, lineMat);
  lineMesh.position.set(0, -0.05, 0.02);
  group.add(lineMesh);

  // 4. IMAGE ASSET INTEGRATION (imageUrl: /prism-mock/home/nodes/orb-decor.png)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Small decoration thumbnail within the card
      const thumbGeom = new ThreePlaneGeometry(0.6, 0.6);
      const thumbMat = new MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        opacity: 0.85
      });
      const thumbMesh = new ThreeMesh(thumbGeom, thumbMat);
      thumbMesh.position.set(0, 0.5, 0.03);
      group.add(thumbMesh);
    }).catch(err => console.warn("Failed to load orb-decor image:", err));
  }

  // 5. MOTION ENTRANCE (GSAP weighted-settle)
  // Ensure we transition into view cleanly
  group.position.y += 0.3;
  group.scale.set(0.9, 0.9, 0.9);

  const settleTimeline = gsap.timeline();
  settleTimeline.to(group.position, {
    y: 0,
    duration: 0.9,
    ease: "power4.out"
  });
  settleTimeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: "power4.out"
  }, "<");

  // No custom interactions as per "static composition" effects spec.

  // 6. CLEANUP
  group.userData = {
    cleanup() {
      settleTimeline.kill();
      geometry.dispose();
      material.dispose();
      lineGeom.dispose();
      lineMat.dispose();
    }
  };

  return group;
}
